('advanced-native-333', '["phrase"]'::jsonb, '{"advanced-native-333-v1-audio":{"type":"mc","answers":["Unclear language and inaccessible timing information create barriers."],"options":["Newcomers already know the terms, and the only issue is that all places are full.","The welcome guarantees that the application process is understandable.","Unclear language and inaccessible timing information create barriers.","A clear guide has already answered the newcomers’ questions."]},"advanced-native-333-v2-reply":{"type":"mc","answers":["The welcoming message does not match the inaccessible application details.","The jargon is unexplained and the dates are hard to find.","The process requires information that newcomers cannot easily obtain.","The jargon and hidden dates put up invisible walls."],"options":["The welcoming message does not match the inaccessible application details.","The jargon is unexplained and the dates are hard to find.","The process requires information that newcomers cannot easily obtain.","The jargon and hidden dates put up invisible walls."]},"advanced-native-333-v1-scene":{"type":"mc","answers":["The details put up invisible walls despite the public welcome."],"options":["The open label alone proves that every newcomer can follow the process.","The published dates are enough to make the process clear, even though the shorthand remains unexplained.","The details put up invisible walls despite the public welcome."]},"advanced-native-333-v1-contrast":{"type":"mc","answers":["Publishing clear dates, plain instructions and a contact for questions."],"options":["Using insider terms without explanation in the only entry guide.","Publishing clear dates, plain instructions and a contact for questions.","Expecting newcomers to know unwritten rules before anyone explains them."]},"advanced-native-333-v1-branch":{"type":"mc","answers":["A clear and necessary rule can support participation; we should identify what actually blocks access."],"options":["Any disagr